from unittest.mock import MagicMock

import pytest

from app.core.config import Settings


def _run_lifespan(monkeypatch: pytest.MonkeyPatch, settings: Settings) -> tuple[MagicMock, MagicMock, MagicMock]:
    """Patches app.main's seams and drives one full lifespan enter+exit cycle.

    Returns the (create_all, start_scheduler, start_pta_scheduler) mocks so callers
    can assert on call counts regardless of whether lifespan raised or not.
    """
    from app import main as main_module

    monkeypatch.setattr(main_module, "get_settings", lambda: settings)

    create_all_mock = MagicMock()
    monkeypatch.setattr(main_module.Base.metadata, "create_all", create_all_mock)

    scheduler_mock = MagicMock(return_value=MagicMock())
    pta_scheduler_mock = MagicMock(return_value=MagicMock())
    monkeypatch.setattr(main_module, "start_scheduler", scheduler_mock)
    monkeypatch.setattr(main_module, "start_pta_scheduler", pta_scheduler_mock)

    async def _enter_and_exit() -> None:
        async with main_module.lifespan(main_module.app):
            pass

    asyncio.run(_enter_and_exit())
    return create_all_mock, scheduler_mock, pta_scheduler_mock


def _settings(*, app_env: str, dev_mode: bool, firebase_auth_disabled: bool) -> Settings:
    return Settings(app_env=app_env, dev_mode=dev_mode, firebase_auth_disabled=firebase_auth_disabled)


# --- Positive ------------------------------------------------------------------------


def test_default_settings_dev_mode_is_gone_and_app_env_defaults_to_development(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """`Settings.dev_mode` no longer exists -- superseded by `app_env`
    (app/core/config.py:15)."""
    for key in ("DEV_MODE", "APP_ENV", "FIREBASE_AUTH_DISABLED"):
        monkeypatch.delenv(key, raising=False)
    settings = Settings(_env_file=None)
    assert not hasattr(settings, "dev_mode")
    assert settings.app_env == "development"


def test_development_env_with_dev_mode_true_boots_normally(monkeypatch: pytest.MonkeyPatch) -> None:
    settings = _settings(app_env="development", dev_mode=True, firebase_auth_disabled=False)
    create_all_mock, scheduler_mock, pta_scheduler_mock = _run_lifespan(monkeypatch, settings)
    create_all_mock.assert_called_once()
    scheduler_mock.assert_called_once()
    pta_scheduler_mock.assert_called_once()


