@pytest.mark.parametrize(
    "app_env,dev_mode,firebase_auth_disabled,should_raise",
    [
        # dev_mode no longer exists on Settings (superseded by app_env,
        # app/core/config.py:15) -- the kwarg is silently dropped and has zero
        # effect on the fail-closed outcome; only firebase_auth_disabled matters.
        ("production", False, False, False),
        ("production", False, True, True),
        ("production", True, False, False),
        ("production", True, True, True),
        ("development", False, False, False),
        ("development", False, True, False),
        ("development", True, False, False),
        ("development", True, True, False),
    ],
)
def test_fail_closed_matrix(
    monkeypatch: pytest.MonkeyPatch,
    app_env: str,
    dev_mode: bool,
    firebase_auth_disabled: bool,
    should_raise: bool,
) -> None:
    settings = _settings(app_env=app_env, dev_mode=dev_mode, firebase_auth_disabled=firebase_auth_disabled)

    if should_raise:
        from app import main as main_module

        monkeypatch.setattr(main_module, "get_settings", lambda: settings)
        create_all_mock = MagicMock()
        monkeypatch.setattr(main_module.Base.metadata, "create_all", create_all_mock)
        scheduler_mock = MagicMock(return_value=MagicMock())
        pta_scheduler_mock = MagicMock(return_value=MagicMock())
        monkeypatch.setattr(main_module, "start_scheduler", scheduler_mock)
        monkeypatch.setattr(main_module, "start_pta_scheduler", pta_scheduler_mock)

        async def _enter() -> None:
            async with main_module.lifespan(main_module.app):
                pass

        with pytest.raises(RuntimeError):
            asyncio.run(_enter())
        create_all_mock.assert_not_called()
    else:
        create_all_mock, _, _ = _run_lifespan(monkeypatch, settings)
        create_all_mock.assert_called_once()


